-- script: main
-- velox:lock-timeout 5s

CREATE SCHEMA IF NOT EXISTS "billing";
CREATE TYPE "billing"."invoices_state" AS ENUM ('open', 'paid');
CREATE TABLE "billing"."payers" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "payers_id_seq") NOT NULL,
  "name" text NOT NULL,
  CONSTRAINT "payers_pkey" PRIMARY KEY ("id")
);
CREATE TABLE "billing"."invoices" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "invoices_id_seq") NOT NULL,
  "state" "billing"."invoices_state" NOT NULL DEFAULT 'open',
  "invoice_payer" bigint NOT NULL,
  CONSTRAINT "invoices_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "invoices_invoice_payer_fkey" FOREIGN KEY ("invoice_payer") REFERENCES "billing"."payers" ("id")
);
CREATE INDEX "invoices_invoice_payer" ON "billing"."invoices" ("invoice_payer");
